import java.nio.file.*;import java.util.*;public final class ProtocolJarEquivalent{static void compare(byte[] left,byte[] right)throws Exception{var n=OpeningDelta.read(left,0);var o=OpeningDelta.read(right,0);if(!n.name.equals(o.name)||n.access!=o.access||!Objects.equals(n.superName,o.superName)||!n.interfaces.equals(o.interfaces)||n.fields.size()!=o.fields.size()||n.methods.size()!=o.methods.size())throw new IllegalStateException("Class shape differs "+n.name);for(var f:n.fields){var old=o.fields.stream().filter(x->x.name.equals(f.name)).findFirst().orElseThrow();if(!old.desc.equals(f.desc)||old.access!=f.access||!Objects.equals(old.value,f.value))throw new IllegalStateException("Field differs "+f.name);}for(var m:n.methods){var old=o.methods.stream().filter(x->OpeningDelta.key(x).equals(OpeningDelta.key(m))).findFirst().orElseThrow();if(old.access!=m.access||!OpeningDelta.eq(old,m))throw new IllegalStateException("Method semantics differ "+OpeningDelta.key(m));}System.out.println("PASS equivalent API/fields/all normalized method bodies "+n.name);}public static void main(String[]a)throws Exception{try(var l=new java.util.zip.ZipFile(a[0]);var r=new java.util.zip.ZipFile(a[1])){int count=0;for(String prefix:java.util.Arrays.copyOfRange(a,2,a.length)){var names=new java.util.TreeSet<String>();for(var en:java.util.Collections.list(l.entries()))if(en.getName().startsWith(prefix)&&en.getName().endsWith(".class"))names.add(en.getName());if(names.isEmpty())throw new IllegalStateException("missing family "+prefix);for(var name:names){var e=r.getEntry(name);if(e==null)throw new IllegalStateException("missing counterpart "+name);compare(l.getInputStream(l.getEntry(name)).readAllBytes(),r.getInputStream(e).readAllBytes());count++;}}System.out.println("PASS protocol families all class methods equivalent count="+count);}}}